            a = b;
            b = t;
        }
        return a;
    };

    const g = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            g[i][j] = gcd(nums[i], nums[j]);
