    }

    const bitCount = Array(full).fill(0);
    for (let mask = 1; mask < full; mask++) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    const dp = Array(full).fill(0);

    for (let mask = 0; mask < full; mask++) {
        const used = bitCount[mask];
        if (used % 2 !== 0) continue;

        const op = used / 2 + 1;

        let first = -1;
        for (let i = 0; i < m; i++) {
