var clumsy = function(n) {
    const stack = [n];
    let op = 0;

    for (let x = n - 1; x >= 1; x--) {
        if (op === 0) {
            stack[stack.length - 1] *= x;
        } else if (op === 1) {
            stack[stack.length - 1] = Math.trunc(stack[stack.length - 1] / x);
