var numSmallerByFrequency = function(queries, words) {
    const f = (s) => {
        let smallest = '{';
        let count = 0;

        for (const ch of s) {
            if (ch < smallest) {
                smallest = ch;
                count = 1;
            } else if (ch === smallest) {
                count++;
            }
        }

        return count;
    };

    const wordFreqs = words.map(f).sort((a, b) => a - b);
    const answer = [];

    for (const query of queries) {
        const queryFreq = f(query);
        let left = 0;
        let right = wordFreqs.length;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);

            if (wordFreqs[mid] <= queryFreq) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        answer.push(wordFreqs.length - left);
    }

    return answer;
};
