    const rowPrefix = Array.from({ length: m }, () => Array(n + 1).fill(0));
    const colPrefix = Array.from({ length: m + 1 }, () => Array(n).fill(0));
    const diagPrefix = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    const antiDiagPrefix = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPrefix[i][j + 1] = rowPrefix[i][j] + grid[i][j];
            colPrefix[i + 1][j] = colPrefix[i][j] + grid[i][j];
            diagPrefix[i + 1][j + 1] = diagPrefix[i][j] + grid[i][j];
        }
    }

    for (let i = 0; i < m; i++) {
        for (let j = n - 1; j >= 0; j--) {
            antiDiagPrefix[i + 1][j] = antiDiagPrefix[i][j + 1] + grid[i][j];
        }
    }

    const maxSize = Math.min(m, n);

    for (let k = maxSize; k >= 1; k--) {
        for (let r = 0; r + k <= m; r++) {
            for (let c = 0; c + k <= n; c++) {
                const target = diagPrefix[r + k][c + k] - diagPrefix[r][c];
                const antiDiagSum = antiDiagPrefix[r + k][c] - antiDiagPrefix[r][c + k];

                if (antiDiagSum !== target) continue;

                let isMagic = true;

                for (let i = r; i < r + k; i++) {
                    const rowSum = rowPrefix[i][c + k] - rowPrefix[i][c];
                    if (rowSum !== target) {
                        isMagic = false;
                        break;
