 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const arr = [];
    let alreadyFull = 0;

    for (const f of flowers) {
        if (f >= target) alreadyFull++;
        else arr.push(f);
    }

    const m = arr.length;
    if (m === 0) return alreadyFull * full;

    arr.sort((a, b) => a - b);

    const prefix = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    const upperBound = (right, value) => {
        let left = 0;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (arr[mid] <= value) left = mid + 1;
            else right = mid;
        }
        return left;
    };

    const bestPartial = (len, budget) => {
        let left = arr[0];
        let right = target - 1;
        let ans = arr[0];

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            const count = upperBound(len, mid);
            const cost = mid * count - prefix[count];

            if (cost <= budget) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    };

    let answer = 0;

    for (let madeFull = 0; madeFull <= m; madeFull++) {
        const suffixSum = prefix[m] - prefix[m - madeFull];
        const costToFull = madeFull * target - suffixSum;

        if (costToFull > newFlowers) break;

        const remaining = newFlowers - costToFull;
        const incompleteCount = m - madeFull;

        let beauty = (alreadyFull + madeFull) * full;

        if (incompleteCount > 0) {
            beauty += bestPartial(incompleteCount, remaining) * partial;
        }

        answer = Math.max(answer, beauty);
    }

    return answer;
};
