/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const total = n * n * 4;
    const parent = new Int32Array(total);
    const rank = new Int32Array(total);

    for (let i = 0; i < total; i++) parent[i] = i;

    let regions = total;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a, b) => {
        const rootA = find(a);
        const rootB = find(b);

        if (rootA === rootB) return;

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        regions--;
    };

    const index = (r, c, part) => {
        return (r * n + c) * 4 + part;
    };

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];

            const top = index(r, c, 0);
            const right = index(r, c, 1);
            const bottom = index(r, c, 2);
            const left = index(r, c, 3);

            if (ch === ' ') {
                union(top, right);
                union(right, bottom);
                union(bottom, left);
            } else if (ch === '/') {
                union(top, left);
                union(right, bottom);
            } else {
                union(top, right);
                union(bottom, left);
            }

            if (r + 1 < n) {
                union(bottom, index(r + 1, c, 0));
            }

            if (c + 1 < n) {
                union(right, index(r, c + 1, 3));
            }
        }
    }

    return regions;
};
