/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var medianSlidingWindow = function(nums, k) {
    class Heap {
        constructor(compare) {
            this.data = [];
            this.compare = compare;
        }

        size() {
            return this.data.length;
        }

        peek() {
            return this.data[0];
        }

        push(value) {
            this.data.push(value);
            this._siftUp(this.data.length - 1);
        }

        pop() {
            const top = this.data[0];
            const last = this.data.pop();

            if (this.data.length > 0) {
                this.data[0] = last;
                this._siftDown(0);
            }

            return top;
        }

        _siftUp(index) {
            while (index > 0) {
                const parent = Math.floor((index - 1) / 2);

                if (!this.compare(this.data[index], this.data[parent])) {
                    break;
                }

                [this.data[index], this.data[parent]] = [this.data[parent], this.data[index]];
                index = parent;
            }
        }

        _siftDown(index) {
            const n = this.data.length;

            while (true) {
                let best = index;
                const left = index * 2 + 1;
                const right = index * 2 + 2;

                if (left < n && this.compare(this.data[left], this.data[best])) {
                    best = left;
                }

                if (right < n && this.compare(this.data[right], this.data[best])) {
                    best = right;
                }

                if (best === index) {
                    break;
                }

                [this.data[index], this.data[best]] = [this.data[best], this.data[index]];
                index = best;
            }
        }
    }

    const small = new Heap((a, b) => a > b);
    const large = new Heap((a, b) => a < b);
    const delayed = new Map();

    let smallSize = 0;
    let largeSize = 0;

    const prune = (heap) => {
        while (heap.size() > 0) {
            const num = heap.peek();
            const count = delayed.get(num) || 0;

            if (count === 0) {
                break;
            }

            heap.pop();

            if (count === 1) {
                delayed.delete(num);
            } else {
                delayed.set(num, count - 1);
            }
        }
    };

    const balance = () => {
        if (smallSize > largeSize + 1) {
            large.push(small.pop());
            smallSize--;
            largeSize++;
            prune(small);
        } else if (smallSize < largeSize) {
            small.push(large.pop());
            smallSize++;
            largeSize--;
            prune(large);
        }
    };

    const add = (num) => {
        if (small.size() === 0 || num <= small.peek()) {
            small.push(num);
            smallSize++;
        } else {
            large.push(num);
            largeSize++;
        }

        balance();
    };

    const remove = (num) => {
        delayed.set(num, (delayed.get(num) || 0) + 1);

        if (num <= small.peek()) {
            smallSize--;

            if (num === small.peek()) {
                prune(small);
            }
        } else {
            largeSize--;

            if (large.size() > 0 && num === large.peek()) {
                prune(large);
            }
        }

        balance();
    };

    const getMedian = () => {
        prune(small);
        prune(large);

        if (k % 2 === 1) {
            return small.peek();
        }

        return (small.peek() + large.peek()) / 2;
    };

    const result = [];

    for (let i = 0; i < k; i++) {
        add(nums[i]);
    }

    result.push(getMedian());

    for (let i = k; i < nums.length; i++) {
        add(nums[i]);
        remove(nums[i - k]);
        result.push(getMedian());
    }

    return result;
};
