    for (const ch of target) {
        if (!available[ch.charCodeAt(0) - 97]) return -1;
    }

    const filtered = [];

    for (const cnt of counts) {
        let dominated = false;

        for (let i = filtered.length - 1; i >= 0; i--) {
            const other = filtered[i];
            let otherDominates = true;
            let cntDominates = true;

            for (let c = 0; c < 26; c++) {
                if (other[c] < cnt[c]) otherDominates = false;
                if (cnt[c] < other[c]) cntDominates = false;
            }

            if (otherDominates) {
                dominated = true;
                break;
            }

            if (cntDominates) {
                filtered.splice(i, 1);
            }
        }

        if (!dominated) filtered.push(cnt);
