        const first = remain.charCodeAt(0) - 97;
        let best = Infinity;

        for (const sticker of filtered) {
            if (sticker[first] === 0) continue;

            const next = [];

            for (let c = 0; c < 26; c++) {
                const left = remCnt[c] - sticker[c];
                for (let k = 0; k < left; k++) {
                    next.push(letters[c]);
